//
//  JobContracts.swift
//  Kalsmritikosh
//
//  Final completion instructions §3 — the contract of every advertised job (168): the professional
//  question it answers, the typed result it must produce, the method or policy that governs it, the
//  human judgement it needs, what happens when input is missing or the evidence is inconclusive, and
//  a concrete acceptance scenario. `status` is the honest state of the result today:
//    • studio  — a specialist work product exists (unit-verified); its journey is not yet verified;
//    • executor — a shared executor produces and persists the job's typed result when the job is
//      launched (integration-verified); its UI journey is not yet verified;
//    • service — the shared case service's result is the job's intended outcome; journey not yet verified;
//    • gap     — the intended result is not produced yet; the job returns only its kind's generic rows.
//  docs/JOB_CONTRACTS.md is generated from this table by JobContractTests.
//

import Foundation

public nonisolated enum JobResultFamily: String, Sendable, CaseIterable {
    case intakeScope, caseQuestion, methodRun, dataAnalysis, sourceExhibitInventory, peopleIdentity, chronologyLinkage,
         issueEvidenceMatrix, interviewsQuotes, reliabilityConflicts, hypothesesCausation, monetaryWorkpapers,
         researchCitation, controlledDisclosure, findingsPublicationProof, actionEffectivenessClosure, personalRecordsBinder

    /// What every job of this family does when its input is missing, the evidence is negative or
    /// inconclusive, or access is denied — the shared part of each contract.
    public var whenIncomplete: String {
        switch self {
        case .intakeScope: return "No scope, no case: nothing is answered until sources are authorised; a source outside scope is never used."
        case .caseQuestion: return "No supporting passage: an honest refusal naming what was searched; conflicting passages: both shown; denied source: not used."
        case .methodRun: return "Missing inputs block the run with the missing list; an inconclusive run is saved as inconclusive, not as a finding."
        case .dataAnalysis: return "Unreadable rows are listed, not dropped; a result over partial data says so."
        case .sourceExhibitInventory: return "A missing or unreadable source stays listed as missing; it never counts as reviewed."
        case .peopleIdentity: return "Ambiguous identities stay separate until a person decides; a merge is reversible."
        case .chronologyLinkage: return "Undated items are labelled undated; disputed dates are shown both ways; a link without a source is not drawn."
        case .issueEvidenceMatrix: return "An element or claim without evidence shows as unsupported; contrary evidence is always listed."
        case .interviewsQuotes: return "Quotes are verbatim with their source; corrections append and never overwrite; an unanswered request is recorded as unanswered (no admission)."
        case .reliabilityConflicts: return "An unassessed source is shown as unassessed; a conflict stays open with both sides until resolved."
        case .hypothesesCausation: return "A cause or hypothesis without evidence stays a hypothesis; an inconclusive analysis is saved as inconclusive."
        case .monetaryWorkpapers: return "Unreadable amounts and unstated currencies block totals; unexplained differences are differences, not loss or fraud."
        case .researchCitation: return "Nil searches are recorded with coverage; a citation missing metadata is flagged; absence proves nothing beyond the coverage searched."
        case .controlledDisclosure: return "Anything not positively cleared is withheld; a protected item never appears in the output; a failed check blocks the package."
        case .findingsPublicationProof: return "A finding without its required evidence or response opportunity is blocked; an inconclusive result is reported as inconclusive."
        case .actionEffectivenessClosure: return "Actions close only by a person with a note; an ineffective action reopens its finding; closure is reversible by reopening."
        case .personalRecordsBinder: return "Old or expired items are flagged, not dropped; nothing sensitive is included in a pack unless chosen."
        }
    }
}

public nonisolated enum JobContractStatus: String, Sendable { case studio, executor, preparation, service, gap }

public nonisolated struct JobContract: Sendable {
    public let job: String
    public let status: JobContractStatus
    public let family: JobResultFamily
    public let question: String
    public let result: String
    public let policy: String
    public let human: String
    public let acceptance: String
}

